use rustred::algebra::{Coefficient,CoefficientPolynomial as Poly};
use rustred::persistence::{CoefficientId,DecodedCoefficientTable};
use symbolica::prelude::*;
use symbolica::poly::gcd::PolynomialGCD;
use symbolica::domains::rational_polynomial::FromNumeratorAndDenominator;
use std::{collections::BTreeMap,time::Instant,panic::{catch_unwind,AssertUnwindSafe}};
#[derive(Clone,Copy)]struct Caps{terms:usize,degree:u64,bits:u64,pairs:u64,total_pairs:u64,bit_products:u128}
impl Default for Caps{fn default()->Self{Self{terms:65536,degree:4096,bits:32768,pairs:4_000_000,total_pairs:64_000_000,bit_products:1u128<<46}}}
impl Caps{fn json(self)->serde_json::Value{serde_json::json!({"terms":self.terms,"degree":self.degree,"coefficient_bits":self.bits,"operation_pairs":self.pairs,"total_operation_pairs":self.total_pairs,"bit_products":self.bit_products.to_string(),"input_count":32})}}
#[derive(Debug)]enum Error{Declined(String),Fatal(String)}
type Result<T>=std::result::Result<T,Error>;
struct CanonicalBatch{values:Vec<Coefficient>}
impl CanonicalBatch{fn checked(values:Vec<Coefficient>)->Result<Self>{if values.len()>32{return Err(Error::Fatal("more than 32 inputs".into()));}for c in &values{if c.denominator.is_zero(){return Err(Error::Fatal("zero denominator".into()));}if c.numerator.variables()!=c.denominator.variables()||c.get_variables()!=values[0].get_variables(){return Err(Error::Fatal("variable map mismatch".into()));}let normalized=catch_unwind(AssertUnwindSafe(||Coefficient::from_num_den(c.numerator.clone(),c.denominator.clone(),c.numerator.ring(),true))).map_err(|_|Error::Fatal("canonical input normalization failed".into()))?;if &normalized!=c{return Err(Error::Fatal("noncanonical coefficient".into()));}}Ok(Self{values})}}
#[derive(Default)]struct Stats{operation_pairs:u64,operations:usize,peak_terms:usize,peak_bits:u64,phase_seconds:BTreeMap<&'static str,f64>}
impl Stats{fn json(&self)->serde_json::Value{serde_json::json!({"operation_pairs":self.operation_pairs,"operations":self.operations,"peak_terms":self.peak_terms,"peak_bits":self.peak_bits,"phase_seconds":self.phase_seconds})}}
fn bits(p:&Poly)->u64{p.coefficients.iter().map(Integer::significant_bits).max().unwrap_or(0)}
fn log2ceil(n:u64)->u64{if n<=1{0}else{64-(n-1).leading_zeros()as u64}}
fn limit(ok:bool,name:&str)->Result<()>{if ok{Ok(())}else{Err(Error::Declined(name.into()))}}
fn shape(p:&Poly,c:Caps)->Result<()>{limit(p.nterms()<=c.terms,"retained term cap")?;limit(bits(p)<=c.bits,"retained coefficient-bit cap")?;for i in 0..p.variables().len(){limit(u64::from(p.degree(i))<=c.degree,"retained degree cap")?;}Ok(())}
fn dense_bound(degrees:impl Iterator<Item=u64>,c:Caps)->Result<u64>{let mut n=1u64;for d in degrees{n=n.checked_mul(d+1).ok_or_else(||Error::Declined("dense support overflow".into()))?;limit(n<=c.terms as u64,"dense support cap")?;}Ok(n)}
fn charge(a:&Poly,b:&Poly,c:Caps,s:&mut Stats)->Result<()>{shape(a,c)?;shape(b,c)?;let pairs=(a.nterms()as u64).checked_mul(b.nterms()as u64).ok_or_else(||Error::Declined("pair overflow".into()))?;limit(pairs<=c.pairs,"operation pair cap")?;let total=s.operation_pairs.checked_add(pairs).ok_or_else(||Error::Declined("total pair overflow".into()))?;limit(total<=c.total_pairs,"total pair cap")?;let bit_product=(pairs as u128).checked_mul(bits(a)as u128).and_then(|v|v.checked_mul(bits(b)as u128)).ok_or_else(||Error::Declined("bit-product overflow".into()))?;limit(bit_product<=c.bit_products,"bit-product cap")?;s.operation_pairs=total;Ok(())}
fn native_poly(name:&'static str,c:Caps,s:&mut Stats,f:impl FnOnce()->Poly)->Result<Poly>{let start=Instant::now();let p=catch_unwind(AssertUnwindSafe(f)).map_err(|_|Error::Fatal(format!("native {name} panic")))?;*s.phase_seconds.entry(name).or_default()+=start.elapsed().as_secs_f64();s.operations+=1;shape(&p,c).map_err(|e|Error::Fatal(format!("native {name} exceeded output cap: {e:?}")))?;s.peak_terms=s.peak_terms.max(p.nterms());s.peak_bits=s.peak_bits.max(bits(&p));Ok(p)}
fn gcd(a:&Poly,b:&Poly,c:Caps,s:&mut Stats)->Result<Poly>{charge(a,b,c,s)?;dense_bound((0..a.variables().len()).map(|i|u64::from(a.degree(i).min(b.degree(i)))),c)?;native_poly("denominator-gcd",c,s,||a.gcd(b))}
fn quotient(a:&Poly,b:&Poly,c:Caps,s:&mut Stats)->Result<Poly>{if b.is_zero(){return Err(Error::Fatal("zero exact divisor".into()));}charge(a,b,c,s)?;dense_bound((0..a.variables().len()).map(|i|u64::from(a.degree(i).saturating_sub(b.degree(i)))),c)?;let start=Instant::now();let q=catch_unwind(AssertUnwindSafe(||a.try_div(b))).map_err(|_|Error::Fatal("native exact quotient panic".into()))?.ok_or_else(||Error::Fatal("nonexact polynomial quotient".into()))?;*s.phase_seconds.entry("exact-quotient").or_default()+=start.elapsed().as_secs_f64();s.operations+=1;shape(&q,c).map_err(|e|Error::Fatal(format!("quotient output cap: {e:?}")))?;s.peak_terms=s.peak_terms.max(q.nterms());s.peak_bits=s.peak_bits.max(bits(&q));Ok(q)}
fn product(a:&Poly,b:&Poly,c:Caps,s:&mut Stats)->Result<Poly>{charge(a,b,c,s)?;let pairs=(a.nterms()*b.nterms())as u64;let mut degrees=Vec::new();for i in 0..a.variables().len(){let d=u64::from(a.degree(i))+u64::from(b.degree(i));limit(d<=c.degree&&d<=u16::MAX as u64,"prospective product degree")?;degrees.push(d);}let dense=degrees.iter().try_fold(1u64,|v,d|v.checked_mul(d+1)).unwrap_or(u64::MAX);limit(pairs.min(dense)<=c.terms as u64,"prospective product terms")?;limit(bits(a)+bits(b)+log2ceil(pairs)<=c.bits,"prospective product bits")?;native_poly("polynomial-product",c,s,||a*b)}
fn add(a:&Poly,b:&Poly,c:Caps,s:&mut Stats)->Result<Poly>{shape(a,c)?;shape(b,c)?;let terms=a.nterms().checked_add(b.nterms()).ok_or_else(||Error::Declined("sum term overflow".into()))?;limit(terms<=c.terms,"prospective sum terms")?;limit(bits(a).max(bits(b))+1<=c.bits,"prospective sum bits")?;let total=s.operation_pairs.checked_add(terms as u64).ok_or_else(||Error::Declined("sum work overflow".into()))?;limit(total<=c.total_pairs,"total sum work")?;s.operation_pairs=total;native_poly("polynomial-sum",c,s,||a+b)}
fn raw_lcm(batch:&CanonicalBatch,c:Caps,s:&mut Stats)->Result<Option<Coefficient>>{
 let values=batch.values.iter().filter(|v|!v.is_zero()).collect::<Vec<_>>();let Some(first)=values.first()else{return Ok(None);};for v in &values{shape(&v.numerator,c)?;shape(&v.denominator,c)?;}
 let mut common=first.denominator.clone();for v in values.iter().skip(1){if common==v.denominator{continue;}let g=gcd(&common,&v.denominator,c,s)?;let rest=quotient(&v.denominator,&g,c,s)?;common=product(&common,&rest,c,s)?;}
 let mut numerators=Vec::with_capacity(values.len());for v in values{let ratio=quotient(&common,&v.denominator,c,s)?;numerators.push(product(&v.numerator,&ratio,c,s)?);}
 while numerators.len()>1{let mut next=Vec::with_capacity(numerators.len().div_ceil(2));let mut it=numerators.into_iter();while let Some(a)=it.next(){next.push(match it.next(){Some(b)=>add(&a,&b,c,s)?,None=>a});}numerators=next;}
 let numerator=numerators.pop().unwrap();if numerator.is_zero(){return Ok(None);}charge(&numerator,&common,c,s)?;dense_bound((0..numerator.variables().len()).map(|i|u64::from(numerator.degree(i).min(common.degree(i)))),c)?;
 let start=Instant::now();let result=catch_unwind(AssertUnwindSafe(||Coefficient::from_num_den(numerator,common,first.numerator.ring(),true))).map_err(|_|Error::Fatal("native final normalization panic".into()))?;*s.phase_seconds.entry("final-canonical-normalization").or_default()+=start.elapsed().as_secs_f64();shape(&result.numerator,c).map_err(|e|Error::Fatal(format!("canonical numerator cap: {e:?}")))?;shape(&result.denominator,c).map_err(|e|Error::Fatal(format!("canonical denominator cap: {e:?}")))?;if result.denominator.is_zero()||result.denominator.lcoeff().is_negative()||result.get_variables()!=first.get_variables(){return Err(Error::Fatal("invalid canonical output".into()));}Ok(Some(result))
}
fn sequential(values:&[Coefficient])->Option<Coefficient>{let mut total:Option<Coefficient>=None;for v in values{total=Some(match total{Some(a)=>&a+v,None=>v.clone()});}total.filter(|v|!v.is_zero())}
fn balanced(mut values:Vec<Coefficient>)->Option<Coefficient>{values.retain(|v|!v.is_zero());while values.len()>1{let mut next=Vec::with_capacity(values.len().div_ceil(2));let mut it=values.into_iter();while let Some(a)=it.next(){if let Some(b)=it.next(){let v=&a+&b;if !v.is_zero(){next.push(v);}}else{next.push(a);}}values=next;}values.pop()}
fn with_fallback(batch:&CanonicalBatch,c:Caps)->Result<(Option<Coefficient>,serde_json::Value)>{let mut s=Stats::default();let start=Instant::now();match raw_lcm(batch,c,&mut s){Ok(v)=>Ok((v,serde_json::json!({"accepted":true,"attempt_seconds":start.elapsed().as_secs_f64(),"stats":s.json()}))),Err(Error::Declined(reason))=>{let elapsed=start.elapsed().as_secs_f64();let t=Instant::now();let v=sequential(&batch.values);Ok((v,serde_json::json!({"accepted":false,"decline":reason,"attempt_seconds":elapsed,"fallback_seconds":t.elapsed().as_secs_f64(),"stats":s.json()})))},Err(e)=>Err(e)}}
#[cfg(test)]mod tests{use super::*;use rustred::algebra::CoefficientContext;
 fn c()->CoefficientContext{CoefficientContext::try_new(["lcm_x","lcm_y"]).unwrap()}
 #[test]fn exact_generic_rationals_cancellations_signs(){let c=c();let x=c.parameter("lcm_x").unwrap();let y=c.parameter("lcm_y").unwrap();let a=&c.one()/&x;let b=&c.one()/&y;let d=-(&(&x+&y)/&(&x*&y));for values in [vec![],vec![c.zero()],vec![a.clone(),b.clone(),d],vec![a.clone(),-a.clone(),b.clone()],vec![a.clone(),&(&x-&c.one())/&x],vec![c.integer(-3),a.clone(),b]]{let expected=sequential(&values);let batch=CanonicalBatch::checked(values).unwrap();let(v,meta)=with_fallback(&batch,Default::default()).unwrap();assert!(meta["accepted"].as_bool().unwrap());assert_eq!(v,expected);}}
 #[test]fn reject_invalid_canonical_boundaries(){let c=c();let x=c.parameter("lcm_x").unwrap();let bad=Coefficient{numerator:x.numerator.clone(),denominator:x.numerator.clone()};assert!(matches!(CanonicalBatch::checked(vec![bad]),Err(Error::Fatal(_))));let bad=Coefficient{numerator:x.numerator.clone(),denominator:x.numerator.zero()};assert!(matches!(CanonicalBatch::checked(vec![bad]),Err(Error::Fatal(_))));let neg=Coefficient{numerator:-x.numerator.clone(),denominator:-x.denominator.clone()};assert!(matches!(CanonicalBatch::checked(vec![neg]),Err(Error::Fatal(_))));let d=CoefficientContext::try_new(["lcm_y","lcm_x"]).unwrap();assert!(matches!(CanonicalBatch::checked(vec![x,d.one()]),Err(Error::Fatal(_))));assert!(CanonicalBatch::checked(vec![c.one();33]).is_err());}
 #[test]fn preflight_decline_preserves_original_order(){let c=c();let x=c.parameter("lcm_x").unwrap();let y=c.parameter("lcm_y").unwrap();let values=vec![&c.one()/&x,&c.one()/&y];let expected=sequential(&values);let batch=CanonicalBatch::checked(values).unwrap();for cap in [Caps{pairs:0,..Default::default()},Caps{degree:0,..Default::default()},Caps{bits:0,..Default::default()},Caps{terms:0,..Default::default()},Caps{bit_products:0,..Default::default()}]{let(v,r)=with_fallback(&batch,cap).unwrap();assert_eq!(r["accepted"],false);assert_eq!(v,expected);}}
 #[test]fn failed_exact_division_is_not_fallback(){let c=c();let x=c.parameter("lcm_x").unwrap();assert!(matches!(quotient(&c.one().numerator,&x.numerator,Default::default(),&mut Stats::default()),Err(Error::Fatal(_))));}
 #[test]fn buffer_boundary_and_adversarial_growth(){let c=c();let x=c.parameter("lcm_x").unwrap();let mut v=Vec::new();for i in 0..32{v.push(&c.integer(if i%2==0{1}else{-1})/&(&x+&c.integer(i/2+1)));}let expected=sequential(&v);let b=CanonicalBatch::checked(v).unwrap();let(v,_)=with_fallback(&b,Default::default()).unwrap();assert_eq!(v,expected);}
}
fn main(){let args=std::env::args().collect::<Vec<_>>();let inp=std::path::PathBuf::from(&args[1]);let out=std::path::PathBuf::from(&args[2]);let metadata:serde_json::Value=serde_json::from_slice(&std::fs::read(inp.join("samples.json")).unwrap()).unwrap();let table=DecodedCoefficientTable::import_generated_normalized(&std::fs::read(inp.join("symbolica-state.bin")).unwrap(),&std::fs::read(inp.join("coefficients.bin")).unwrap(),Default::default()).unwrap();let mut rows=Vec::new();let caps=Caps::default();for(s,r)in metadata["records"].as_array().unwrap().iter().enumerate(){let values=r["ids"].as_array().unwrap().iter().map(|i|table.coefficient(CoefficientId::try_from_index(i.as_u64().unwrap()as usize).unwrap()).unwrap().clone()).collect::<Vec<_>>();let expected=r["expected"].as_u64().map(|i|table.coefficient(CoefficientId::try_from_index(i as usize).unwrap()).unwrap().clone());let start=Instant::now();let batch=CanonicalBatch::checked(values).unwrap();let ingress=start.elapsed().as_secs_f64();let mut runs=Vec::new();for repeat in 0..3{for method in [repeat%3,(repeat+1)%3,(repeat+2)%3]{let start=Instant::now();let(value,detail)=match method{0=>(sequential(&batch.values),serde_json::Value::Null),1=>(balanced(batch.values.clone()),serde_json::Value::Null),2=>with_fallback(&batch,caps).unwrap(),_=>unreachable!()};let seconds=start.elapsed().as_secs_f64();assert_eq!(value,expected);runs.push(serde_json::json!({"repeat":repeat,"method":(["sequential","balanced","raw-lcm"][method]),"seconds":seconds,"detail":detail,"exact_match":true}));}}let mut medians=serde_json::Map::new();for name in ["sequential","balanced","raw-lcm"]{let mut times=runs.iter().filter(|r|r["method"]==name).map(|r|r["seconds"].as_f64().unwrap()).collect::<Vec<_>>();times.sort_by(f64::total_cmp);medians.insert(name.into(),serde_json::json!(times[1]));}rows.push(serde_json::json!({"sample":s,"ordinal":r["ordinal"],"ingress_seconds":ingress,"runs":runs,"medians":medians}));std::fs::write(&out,serde_json::to_vec_pretty(&serde_json::json!({"scope":"only the eight previously selected repeated-denominator buffers; no integral reduction","caps":caps.json(),"completed_samples":rows.len(),"records":rows})).unwrap()).unwrap();println!("sample {s} complete");}}
